using System.Reflection;
using System.Text.Json;
using Yukkuri.Simulation;
int checks=0,failures=0;
void Require(bool ok,string why){if(!ok)throw new Exception(why);}
void Check(string name,Action action){checks++;try{action();Console.WriteLine("PASS "+name);}catch(Exception e){failures++;Console.WriteLine("FAIL "+name+": "+e.Message);}}
var response=typeof(WorldSimulation).GetMethod("TryRespondToWater",BindingFlags.Instance|BindingFlags.NonPublic)!;
var occupancy=typeof(WorldSimulation).GetMethod("CanOccupyRoom",BindingFlags.Instance|BindingFlags.NonPublic)!;
bool Fits(WorldSimulation s,Creature c,double x,double z)=>(bool)occupancy.Invoke(s,new object?[]{c,x,z,null,null,false})!;
void Respond(WorldSimulation s,Creature c,double dt=.1)=>response.Invoke(s,new object[]{c,dt});
(WorldSimulation s,Creature wet,Creature helper) Fixture()
{
 var s=WorldSimulation.CreateInteractionPlaytest();s.State.RoomObjects.RemoveAll(o=>o.Kind!=RoomObjectKind.RiverWater);s.State.AutonomousBreeding=false;
 var wet=s.State.Creatures[1];var helper=s.State.Creatures[0];s.State.Creatures.RemoveAll(c=>c!=wet&&c!=helper);
 wet.X=WoodlandLayout.RiverEdge(0)+.035;wet.Z=0;wet.TargetX=wet.X;wet.TargetZ=0;wet.Interaction.Water.InWater=true;wet.Interaction.Water.EventId="water-test";wet.Interaction.Water.EnteredAt=0;wet.Energy=60;
 helper.X=WoodlandLayout.RiverEdge(0)-WorldSimulation.InteractionFootprint(wet)-.18;helper.Z=1.25;helper.TargetX=helper.X;helper.TargetZ=helper.Z;helper.Fullness=90;helper.Energy=90;helper.Interaction.Hydration=90;helper.Personality.Initialized=true;helper.Personality.Kindness=.8;helper.Personality.NextWaterResponseAt=10000;helper.Interaction.NextAutonomyAt=10000;helper.Family.NextCareAt=10000;
 return(s,wet,helper);
}
Check("kind helper leaves a full-body bank landing through bounded real movement",()=>{var(s,w,h)=Fixture();double x=WoodlandLayout.RiverEdge(0)-WorldSimulation.InteractionFootprint(w)-.18,z=0;for(int n=0;n<40;n++){double oldX=h.X,oldZ=h.Z;Respond(s,h);Require(Math.Sqrt(Math.Pow(h.X-oldX,2)+Math.Pow(h.Z-oldZ,2))<=s.Config.MoveSpeed*.1+1e-8,"helper teleported");}Require(Fits(s,w,x,z),"helper still blocks landing");Require(h.X!=x||h.Z!=z,"helper never yielded");});
Check("dependent-care duty does not keep a kind bystander in the landing",()=>{var(s,w,h)=Fixture();h.Family.CareTargetId=w.Id;double x=WoodlandLayout.RiverEdge(0)-WorldSimulation.InteractionFootprint(w)-.18,z=0;for(int n=0;n<40;n++)Respond(s,h);Require(Fits(s,w,x,z),"care duty keeps landing blocked");Require(h.Family.CareTargetId==w.Id,"yield erased dependent care");});
Check("resting helpers are not moved or granted extra rescue",()=>{var(s,w,h)=Fixture();h.Interaction.Resting=true;h.Interaction.RestRemaining=10;double x=h.X,z=h.Z;Respond(s,h);Require(h.X==x&&h.Z==z&&h.Interaction.RestRemaining==10,"resting body forced aside");});
Check("critical helpers cannot be moved aside",()=>{var(s,w,h)=Fixture();h.Condition=PhysicalCondition.Critical;double x=h.X,z=h.Z;Respond(s,h);Require(h.X==x&&h.Z==z,"critical body moved");});
Check("hostile witnesses are not silently turned into rescuers",()=>{var(s,w,h)=Fixture();h.Personality.Kindness=.05;double x=h.X,z=h.Z;Respond(s,h);Require(h.X==x&&h.Z==z,"hostile witness forced to help");});
Check("save reload keeps the helper able to clear the landing",()=>{var(s,w,h)=Fixture();// Use ordinary serialized fields; no passage reservation is persisted.
 SaveStore.Validate(s.State);var copy=new WorldSimulation(JsonSerializer.Deserialize<WorldState>(JsonSerializer.Serialize(s.State,SaveStore.JsonOptions),SaveStore.JsonOptions)!);var ww=copy.State.Creatures.Single(c=>c.Id==w.Id);var hh=copy.State.Creatures.Single(c=>c.Id==h.Id);double x=WoodlandLayout.RiverEdge(0)-WorldSimulation.InteractionFootprint(ww)-.18;for(int n=0;n<40;n++)Respond(copy,hh);Require(Fits(copy,ww,x,0),"reload stranded helper in passage");});
Check("player contact retains control of the helper",()=>{var(s,w,h)=Fixture();Require(s.BeginInteractionGesture(h.Id,new(InteractionAction.Stroke)).Success,"contact fixture failed");double x=h.X,z=h.Z;Respond(s,h);Require(h.X==x&&h.Z==z,"player-controlled body moved");});
Check("paused world does not move helpers",()=>{var(s,w,h)=Fixture();s.State.Settings.Pause=true;double x=h.X,z=h.Z;s.Advance(5);Require(h.X==x&&h.Z==z,"paused helper moved");});
Check("two kind helpers clear a shared landing without body overlap",()=>{var(s,w,h)=Fixture();var second=JsonSerializer.Deserialize<Creature>(JsonSerializer.Serialize(h,SaveStore.JsonOptions),SaveStore.JsonOptions)!;second.Id="helper-second";second.Body.Id="helper-second-body";second.Registration.IdentityId="helper-second-identity";second.Z=second.TargetZ=-1.25;s.State.Creatures.Add(second);double x=WoodlandLayout.RiverEdge(0)-WorldSimulation.InteractionFootprint(w)-.18;for(int n=0;n<50;n++){Respond(s,h);Respond(s,second);Require(Fits(s,h,h.X,h.Z)&&Fits(s,second,second.X,second.Z),"yield passed through a body or terrain");}Require(Fits(s,w,x,0),"two helpers still occupy landing");});
Check("immobile blockade is not teleported or ignored",()=>{var(s,w,h)=Fixture();h.Interaction.FootIntegrity=0;double x=h.X,z=h.Z;for(int n=0;n<40;n++)Respond(s,h);Require(h.X==x&&h.Z==z,"immobile body displaced");Require(!Fits(s,w,WoodlandLayout.RiverEdge(0)-WorldSimulation.InteractionFootprint(w)-.18,0),"collision was ignored");});
Check("fixed real-world blocked snapshot now reaches shore without changing accident or damage rules",()=>{
 var state=JsonSerializer.Deserialize<WorldState>(File.ReadAllText(Path.Combine(AppContext.BaseDirectory,"WaterBlockedSnapshot.json")),SaveStore.JsonOptions)!;SaveStore.Validate(state);var s=new WorldSimulation(state);var w=state.Creatures.Single(c=>c.Name=="松果");bool sawYield=false;for(int n=0;n<1400&&WaterEnvironment.IsInWater(state,w)&&w.Condition!=PhysicalCondition.Dead;n++){double beforeTime=state.WorldSeconds;var previous=state.Creatures.ToDictionary(c=>c.Id,c=>(c.X,c.Z));s.AdvanceInteractionPresentation(.1);s.Advance(.1);foreach(var h in state.Creatures.Where(c=>c!=w)){if(h.Activity.Contains("腾出")){sawYield=true;var old=previous[h.Id];Require(Math.Sqrt(Math.Pow(h.X-old.X,2)+Math.Pow(h.Z-old.Z,2))<=s.Config.MoveSpeed*(state.WorldSeconds-beforeTime)+1e-7,"snapshot helper teleported");}}}
 Require(!WaterEnvironment.IsInWater(state,w)&&w.Condition!=PhysicalCondition.Dead,"blocked snapshot did not reach shore alive");Require(sawYield,"actual scenario did not exercise yielding");Require(w.Interaction.Water.ExposureSeconds>0&&w.Health<100,"water harm was erased");SaveStore.Validate(state);Console.WriteLine("SNAPSHOT_ESCAPED "+JsonSerializer.Serialize(new{state.WorldSeconds,w.Health,w.Energy,w.Interaction.Water.AttemptOutcome}));});
Check("self-preservation needs do not yield to rescue positioning",()=>{foreach(string need in new[]{"food","water","fear","pain"}){var(s,w,h)=Fixture();if(need=="food")h.Fullness=5;if(need=="water")h.Interaction.Hydration=5;if(need=="fear")h.Fear=80;if(need=="pain")h.Pain=70;double x=h.X,z=h.Z;Respond(s,h);Require(h.X==x&&h.Z==z,need+" was overridden by yielding");}});
Check("two water incidents do not move a helper into the other landing",()=>{var(s,w,h)=Fixture();var wet2=JsonSerializer.Deserialize<Creature>(JsonSerializer.Serialize(w,SaveStore.JsonOptions),SaveStore.JsonOptions)!;wet2.Id="water-second";wet2.Body.Id="water-second-body";wet2.Registration.IdentityId="water-second-identity";wet2.Z=wet2.TargetZ=2.5;wet2.X=wet2.TargetX=WoodlandLayout.RiverEdge(wet2.Z)+.035;wet2.Interaction.Water.EventId="water-second-event";s.State.Creatures.Add(wet2);for(int n=0;n<60;n++){double x=h.X,z=h.Z;Respond(s,h);Require(Math.Sqrt(Math.Pow(h.X-x,2)+Math.Pow(h.Z-z,2))<=s.Config.MoveSpeed*.1+1e-8,"multi-target teleport");Require(Fits(s,h,h.X,h.Z),"multi-target collision");}foreach(var target in new[]{w,wet2}){double r=WorldSimulation.InteractionFootprint(target);Require(Fits(s,target,WoodlandLayout.RiverEdge(target.Z)-r-.18,target.Z),"helper occupied another casualty landing");}});
foreach(bool young in new[]{true,false})Check((young?"young":"adult")+" responder navigates from afar and makes actual peer rescue",()=>{
 var(s,w,h)=Fixture();h.IsYoung=young;h.X=h.TargetX=3;h.Z=h.TargetZ=2.5;h.Personality.NextWaterResponseAt=0;double initialX=h.X,initialZ=h.Z;bool moved=false;
 Require(Fits(s,h,h.X,h.Z),"far helper fixture overlaps terrain");Respond(s,h);Require(WaterEnvironment.IsInWater(s.State,w)&&!w.Interaction.Memories.ContainsKey("peer-water-rescue"),"remote helper rescued without reaching support point");
 for(int n=0;n<1000&&WaterEnvironment.IsInWater(s.State,w);n++){double x=h.X,z=h.Z;s.State.WorldSeconds+=.1;Respond(s,h);double travel=Math.Sqrt(Math.Pow(h.X-x,2)+Math.Pow(h.Z-z,2));Require(travel<=s.Config.MoveSpeed*.1+1e-8,"helper teleported while approaching");moved|=travel>0;Require(Fits(s,h,h.X,h.Z),"helper crossed an occupied point");}
 Require(moved&&Math.Sqrt(Math.Pow(h.X-initialX,2)+Math.Pow(h.Z-initialZ,2))>1,"helper never actually navigated");Require(!WaterEnvironment.IsInWater(s.State,w)&&w.Interaction.Memories.ContainsKey("peer-water-rescue"),"safe standing position never enabled real peer rescue");});
Check("moving casualty invalidates a previously reached support point",()=>{
 var(s,w,h)=Fixture();h.IsYoung=true;h.Personality.NextWaterResponseAt=10000;for(int n=0;n<80;n++)Respond(s,h);w.Z=w.TargetZ=-2.5;w.X=w.TargetX=WoodlandLayout.RiverEdge(w.Z)+.035;h.Personality.NextWaterResponseAt=0;Respond(s,h);Require(WaterEnvironment.IsInWater(s.State,w)&&!w.Interaction.Memories.ContainsKey("peer-water-rescue"),"old support position rescued a moved target");});
Console.WriteLine($"RESULT {checks-failures}/{checks}; failures={failures}");return failures==0?0:1;

